suppressMessages({library(duckdb); library(data.table)})
con <- dbConnect(duckdb()); S <- Sys.getenv("S")
rd <- function(t, yrs=2019:2021) rbindlist(lapply(yrs, function(y) { x<-as.data.table(dbGetQuery(con, sprintf("select * from read_parquet('%s/data/%d/%s-%d.parquet')", S, y, t, y))); x[, FILE_YEAR:=y] }), fill=TRUE)
p1h <- rd("SN-P01-T00-LIQUIDATION-TERMINATION-DISSOLUTION"); p1 <- rd("SN-P01-T01-LIQUIDATION-TERMINATION-DISSOLUTION")
p2h <- rd("SN-P02-T00-DISPOSITION-OF-ASSETS"); p2 <- rd("SN-P02-T01-DISPOSITION-OF-ASSETS"); p3 <- rd("SN-P03-T99-SUPPLEMENTAL-INFO")
saveRDS(list(p1h=p1h,p1=p1,p2h=p2h,p2=p2,p3=p3), file.path(S,"sn.rds"))
cat("filings per file-year:\n"); print(rbind(P1=table(p1h$FILE_YEAR), P1rows=table(unique(p1[,.(OBJECTID,FILE_YEAR)])$FILE_YEAR), P2=table(p2h$FILE_YEAR), P2rows=table(unique(p2[,.(OBJECTID,FILE_YEAR)])$FILE_YEAR)))
cat("TAX_YEAR within file:\n"); print(table(p1h$FILE_YEAR, p1h$TAX_YEAR))
cat("Filings in both P1 and P2:", length(intersect(p1h$OBJECTID, p2h$OBJECTID)), "\n")
cat("EINs with SN in >1 year (P1):", sum(table(unique(p1h[,.(EIN2,TAX_YEAR)])$EIN2)>1), "of", uniqueN(p1h$EIN2), "\n")
cat("amended:", table(p1h$RETURN_AMENDED_X), "\n")
cat("Flag encodings P1:\n"); for (v in grep("_X$", names(p1h), value=TRUE)[-(1:3)]) {cat(v,": "); print(table(p1h[[v]], useNA="ifany"))}
cat("Flag encodings P2 DIR:\n"); print(table(p2h$SN_02_ORG_DTK_DIR_SUCCESSOR_X, useNA="ifany"))
cat("P01 T00 filings with no T01 rows:", length(setdiff(p1h$OBJECTID, p1$OBJECTID)), " P01 T01 filings with no T00:", length(setdiff(p1$OBJECTID,p1h$OBJECTID)),"\n")
cat("P1 recip EIN missing share:", mean(is.na(p1$SN_01_LTD_RECIP_EIN) | p1$SN_01_LTD_RECIP_EIN %in% c("","000000000")), "\n")
cat("P2 recip EIN missing share:", mean(is.na(p2$SN_02_DOA_RECIP_EIN)), "\n")
cat("P1 recipients per filing (distinct EIN or name):\n"); p1[, RK:=fcoalesce(SN_01_LTD_RECIP_EIN, toupper(SN_01_LTD_RECIP_NAME_ORG_L1), toupper(SN_01_LTD_RECIP_NAME_PERS))]
print(table(cut(p1[, uniqueN(RK), by=OBJECTID]$V1, c(0,1,2,3,5,10,Inf))))
cat("Top P1 IRC section values:\n"); print(head(sort(table(toupper(p1$SN_01_LTD_RECIP_IRC_SECTION)), decreasing=TRUE), 30))
cat("Top P2 IRC section values:\n"); print(head(sort(table(toupper(p2$SN_02_DOA_RECIP_IRC_SECTION)), decreasing=TRUE), 25))
p1[, FMV:=as.numeric(SN_01_LTD_ASSET_DIST_FMV)]; cat("P1 FMV summary:\n"); print(summary(p1$FMV)); cat("P1 filing totals summary:\n"); print(summary(p1[,sum(FMV,na.rm=T),by=OBJECTID]$V1))
cat("Top asset descs:\n"); print(head(sort(table(toupper(substr(p1$SN_01_LTD_ASSET_DIST_DESC,1,40))),decreasing=TRUE),25))
cat("Top FMV methods:\n"); print(head(sort(table(toupper(p1$SN_01_LTD_ASSET_DIST_FMV_METHOD)),decreasing=TRUE),15))
cat("P3 line refs:\n"); print(head(sort(table(p3$SN_03_FORM_LINE_REFERENCE),decreasing=TRUE),15))
